function UsageGroupTable({groups,type,select}:{groups:any[];type:'TASK'|'ETL';select:(id:string)=>void}){const sum=(r:any[],k:string)=>r.reduce((n,x)=>n+Number(x[k]??(k==='credits'?x.ai_usage?.ai_credits:0)),0),f=(n:number,d=0)=>n.toLocaleString(undefined,{maximumFractionDigits:d});return groups.length?<div className="table-scroll"><table><thead><tr><th>{type==='TASK'?'Task':'分析 Task／批次'}</th><th>類型／檔案</th><th>呼叫</th><th>Provider</th><th>Token</th><th>Premium Requests</th><th>AIC／AIU</th><th>總耗時</th></tr></thead><tbody>{groups.map(g=><tr key={g.id} onClick={()=>select(g.id)}><td><b>{g.name}</b><small>{g.id}</small></td><td>{type==='TASK'?g.type:`${new Set(g.rows.map((x:any)=>x.source_relative_path)).size} 個 ETL`}</td><td>{g.rows.length}</td><td>{Array.from(new Set(g.rows.map((x:any)=>x.provider))).join('、')}</td><td>{f(sum(g.rows,'total_tokens'))}</td><td>{f(sum(g.rows,'premium_requests'),4)}</td><td>{f(sum(g.rows,'credits'),6)}</td><td>{(sum(g.rows,'duration_ms')/1000).toFixed(1)} 秒</td></tr>)}</tbody></table></div>:<p className="muted">尚無模型用量。</p>}
