 const model=result?.canonical_model;
 return <div className="analyzer-page"><section className="analyzer-hero"><div><span className="eyebrow">ETL LINEAGE / LOGIC ANALYZER</span><h2>建立可稽核的 ETL 技術脈絡</h2><p>以程式化 Parser 解析 Pentaho 與 Apache Hop，系統化呈現流程結構、相依關係、資料來源與目標，以及核心轉換邏輯，作為文件化、影響分析與現代化移轉的技術基礎。</p></div><FileSearch2/></section>{error&&<div className="notice error"><AlertTriangle/>{error}</div>}<div className="analyzer-layout"><div className="panel analyzer-picker"><div className="panelhead"><h3><Search/>選擇掃描檔案</h3><button onClick={()=>load()}><RefreshCw/>重新整理</button></div>{inventory&&<div className="analyzer-counts"><span>全部<b>{inventory.total}</b></span><span>KTR<b>{inventory.counts['.ktr']||0}</b></span><span>KJB<b>{inventory.counts['.kjb']||0}</b></span><span>HPL/HWF<b>{(inventory.counts['.hpl']||0)+(inventory.counts['.hwf']||0)}</b></span></div>}<label>搜尋檔名<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="輸入 Job 或 Transformation 名稱"/></label><label>ETL 檔案<select size={12} value={selectedPath} onChange={e=>setSelectedPath(e.target.value)}>{files.map((x:any)=><option key={x.path} value={x.path}>[{x.extension.slice(1).toUpperCase()}] {x.path}</option>)}</select></label><button className="primary analyzer-run" disabled={!selectedPath||busy} onClick={analyze}><Play/>{busy?'分析中…':'開始分析'}</button><small className="storage-hint">{inventory?.storage_note}</small></div><div className="analyzer-main">{!model?<div className="panel analyzer-empty"><GitBranch/><h3>選擇 ETL 定義檔進行結構化分析</h3><p>分析結果會寫入 PostgreSQL，原始 XML 中的密碼、Token 與 Secret 會先遮蔽。</p></div>:<><div className="panel analysis-head"><div><span className="eyebrow">{model.process.platform} · {model.process.type}</span><h2>{model.process.name}</h2><p>{model.process.source_file}</p></div><span className="status succeeded"><CheckCircle2/>SUCCEEDED</span></div><div className="analysis-stats"><Card label="節點" value={model.nodes.length} note="Step / Entry" color="cyan"/><Card label="流程連線" value={model.edges.length} note="Hop / Branch" color="green"/><Card label="來源 / 目標" value={`${model.sources.length} / ${model.targets.length}`} note="Table / File" color="violet"/><Card label="處理邏輯" value={model.logic.length} note="Filter / Join / Lookup" color="orange"/></div><div className="analysis-tabs">{[['overview','總覽'],['flow','流程'],['lineage','來源與目標'],['logic','處理邏輯'],['dependencies','相依性'],['sql','SQL / 參數']].map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div><div className="panel analysis-body">{tab==='overview'&&<><h3>分析摘要</h3><p className="analysis-summary">{model.summary}</p><div className="analysis-meta"><span>來源平台<b>{model.process.platform}</b></span><span>類型<b>{model.process.type}</b></span><span>檔案大小<b>{Number(model.source_size).toLocaleString()} bytes</b></span><span>Checksum<b title={model.checksum}>{model.checksum.slice(0,16)}…</b></span></div><h3>警告與待確認事項</h3>{model.warnings.length?model.warnings.map((x:any)=><div className="notice" key={x.code}><AlertTriangle/><div><b>{x.message}</b><p>{x.items?.join('、')||x.code}</p></div></div>):<div className="notice success"><CheckCircle2/>目前沒有解析警告</div>}</>}{tab==='flow'&&<FlowView model={model}/>} {tab==='lineage'&&<LineageView model={model}/>} {tab==='logic'&&<LogicView model={model}/>} {tab==='dependencies'&&<><h3>子流程與檔案相依性</h3>{model.dependencies.length?<div className="dependency-list">{model.dependencies.map((x:string)=><div key={x}><GitBranch/><b>{x}</b></div>)}</div>:<p className="muted">此檔案未辨識到子 Job、Transformation、Pipeline 或 Workflow。</p>}<h3>Variables</h3><div className="tag-list">{model.variables.length?model.variables.map((x:string)=><span key={x}>{x}</span>):<span>無</span>}</div></>}{tab==='sql'&&<SqlParameterView model={model}/>}</div></>}</div></div><div className="panel analysis-history"><PanelHead title="最近分析紀錄" action="重新整理" onAction={()=>load()}/>{history.length?<div className="table-scroll"><table><thead><tr><th>ETL</th><th>平台／類型</th><th>節點</th><th>來源／目標</th><th>邏輯</th><th>分析時間</th></tr></thead><tbody>{history.map((x:any)=><tr key={x.analysis_id} onClick={()=>open(x.analysis_id)}><td><b>{x.process_name}</b><small>{x.source_relative_path}</small></td><td>{x.platform_type}<small>{x.process_type}</small></td><td>{x.node_count}</td><td>{x.source_count} / {x.target_count}</td><td>{x.logic_count}</td><td>{new Date(x.created_at).toLocaleString()}</td></tr>)}</tbody></table></div>:<p className="muted">尚無分析紀錄。</p>}</div></div>
