 {level==='models'&&<div className="model-detail-list">{models.map((m:any)=><article className="panel" key={m.key}><div className="model-detail-head"><div><span className="eyebrow">{m.provider}</span><h3>{m.model}</h3></div><b>{m.calls} 次呼叫</b></div><div className="model-detail-metrics"><span>Input Token<b>{fmt(m.input)}</b></span><span>Cached Input<b>{fmt(m.cached)}</b></span><span>Output Token<b>{fmt(m.output)}</b></span><span>Total Token<b>{fmt(m.tokens)}</b></span><span>Premium Requests<b>{fmt(m.premium,2)}</b></span><span>AIU<b>{fmt(m.credits,5)}</b></span><span>平均耗時<b>{m.calls?(m.duration/m.calls/1000).toFixed(1):0} 秒</b></span><span>資料完整度<b>{m.rows.every((x:any)=>x.usage_type==='EXACT')?'完整':'部分'}</b></span></div><UsageCallTable rows={m.rows.map((x:any)=>({...x,time:x.started_at,credits:x.ai_credits,usage_source:x.raw_usage?.source}))}/></article>)}</div>}
