 const [settings,setSettings]=useState<any>(null),[busy,setBusy]=useState(false),[uploading,setUploading]=useState<number|null>(null),[form,setForm]=useState<any>({name:'',requirement:'',operation:'NEW',category:'STAGE',source_type:'CSV',source_config:{has_actual_data:true,sources:[make('CSV')]},target_type:'VERTICA',target_schema:'public',target_table:'validation_output',model:'copilot',error_test_config:{}});useEffect(()=>{api('/api/settings').then(setSettings).catch(e=>onError(e.message))},[]);
