 const chooseError=(value:string)=>{const x=errorScenarios.find(y=>y.scenario===value)||errorScenarios[0];setForm({...form,operation:'ERROR_TEST',category:'STAGE',source_type:'CSV',source_config:{sources:[{...make('CSV'),has_actual_data:false,alias:'error_test',fields:[{name:'record_id',type:'INT'}]}]},target_schema:'public',target_table:'generated_error_test_data',error_test_config:{enabled:true,node:x.node,scenario:x.scenario,expected_error_code:x.code,description:x.label}})};const selected=errorScenarios.find(x=>x.scenario===form.error_test_config?.scenario)||errorScenarios[0];
