 const sourceOk=sources.every((s:any)=>{if(!s.alias)return false;if(form.category==='STAGE'&&stageMode==='EXTERNAL')return s.has_actual_data?!!s.path&&s.fields?.length&&s.fields.every((f:any)=>f.name&&f.type):s.fields?.length&&s.fields.every((f:any)=>f.name&&f.type);if(form.category==='STAGE'&&stageMode==='FLEX')return s.has_actual_data?!!s.path:s.fields?.length&&s.fields.every((f:any)=>f.name&&f.type);return s.has_actual_data?(s.type==='VERTICA'?s.schema&&s.object:s.path):s.fields?.length&&s.fields.every((f:any)=>f.name&&f.type)});const shapeOk=form.category==='STAGE'?sources.length===1&&['CSV','EXCEL','JSON'].includes(sources[0]?.type):form.category==='ODS'?sources.length===1&&sources[0]?.type==='VERTICA':sources.length>=2&&sources.every((s:any)=>s.type==='VERTICA');const valid=form.name.trim().length>=2&&form.requirement.trim().length>=5&&form.target_schema&&form.target_table&&(form.operation==='ERROR_TEST'||(sourceOk&&shapeOk));
 const submit=async()=>{setBusy(true);try{const normalizedSources=sources.map((source:any)=>form.category==='STAGE'&&stageMode==='FLEX'?{...source,type:(source.parser_format||'JSON')==='JSON'?'JSON':'CSV'}:source);const primary=normalizedSources[0]||{};const directory=String(stageConfig.data_directory||'').replace(/\/+$/,'');const pattern=String(primary.file_pattern||(stageMode==='FLEX'?'*.json':'*.csv')).replace(/^\/+/, '');const targetConfig=form.category==='STAGE'?{...stageConfig,data_path:stageMode==='NORMAL'?'':`${directory}/${pattern}`,delimiter:primary.delimiter||',',quote:primary.quote||'"',header:primary.header!==false,format:primary.parser_format||'JSON'}:{stage_mode:'NORMAL'};const payload={...form,source_type:primary.type||form.source_type,source_config:{...(form.source_config||{}),sources:normalizedSources},target_config:targetConfig};onCreated(await api('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}))}catch(e:any){onError(e.message)}finally{setBusy(false)}};
