 const saveConnectionSecret=async()=>{try{if(!connectionSecret.trim())throw new Error('請輸入資料庫密碼或連線 token');setBusy(true);await api(`/api/settings/connections/${connectionId}/secret`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({secret_value:connectionSecret})});setConnectionSecret('');setMessage('資料庫連線機密已加密儲存') }catch(e:any){setMessage(`儲存失敗：${e.message}`)}finally{setBusy(false)}};
