function ProjectTaskDetailPanel({taskId,onClose,onError}:{taskId:string;onClose:()=>void;onError:(s:string)=>void}){const [task,setTask]=useState<any>(null);useEffect(()=>{api(`/api/tasks/${taskId}`).then(setTask).catch(e=>onError(e.message))},[taskId]);if(!task)return <div className="panel"><p>正在讀取 Task 詳細資訊…</p></div>;return <section className="panel project-task-detail"><div className="panelhead"><div><span className="eyebrow">{task.id}</span><h3>{task.name}</h3></div><button onClick={onClose}>返回歷史 Task</button></div><p>{task.requirement}</p><div className="config-grid"><article><small>狀態</small><b>{task.status}</b></article><article><small>進度</small><b>{task.progress}%</b></article><article><small>來源</small><b>{task.source}</b></article><article><small>目標</small><b>{task.target}</b></article></div><h3>執行節點</h3><div className="tasklist">{(task.nodes||[]).map((n:any)=><div className="node" key={n.key}><span className={String(n.status).toLowerCase()}>{n.status==='SUCCEEDED'?'✓':'•'}</span><div><b>{n.label}</b><small>{n.status}{n.duration_ms!=null?` · ${Math.round(n.duration_ms)} ms`:''}</small></div></div>)}</div><h3>Task 設定</h3><div className="detailfacts"><span>AI Model<b>{task.model||'—'}</b></span><span>建立時間<b>{task.created_at?new Date(task.created_at).toLocaleString():'—'}</b></span><span>寫入筆數<b>{task.rows||0}</b></span></div>{task.last_error&&<div className="notice error"><AlertTriangle/><div><b>{task.last_error.code||'執行異常'}</b><p>{task.last_error.action||task.last_error.error}</p></div></div>}<h3>執行紀錄</h3><div className="terminal">{(task.logs||[]).length?(task.logs||[]).map((l:any,i:number)=><code key={i}>[{new Date(l.time).toLocaleTimeString()}] {l.level} {l.node||''} — {l.message}</code>):<code>尚無執行紀錄</code>}</div></section>}
